window.CODE = Object.assign(window.CODE || {}, {"ch35/build_dataset.py":"\"\"\"Turn production traces into a fine-tuning dataset. Every step removes a way for fine-tuning to go wrong.\n\n    keep only good examples -> remove unsafe replies -> scrub personal data -> remove duplicates ->\n    remove anything that is in the EVALUATION set (contamination) -> split -> write JSONL in chat format\n\"\"\"\nimport json\nimport random\nimport re\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch33\"))\nsys.path.insert(0, str(HERE.parent / \"ch27\"))\nsys.path.insert(0, str(HERE.parent / \"ch31\"))\nfrom pii import redact_regex  # noqa: E402  (Chapter 33)\nfrom safety import MEDICAL  # noqa: E402  (Chapter 27)\nfrom dataset import STARTER  # noqa: E402  (Chapter 31's evaluation cases)\n\nSYSTEM = \"You are the City Clinic helpdesk. Answer briefly, only with facts you were given, never give medical advice.\"\n\n\ndef _norm(text: str) -> frozenset:\n    return frozenset(re.findall(r\"[a-z0-9]+\", text.lower()))\n\n\ndef _jaccard(a, b) -> float:\n    return len(a & b) / len(a | b) if a | b else 1.0\n\n\ndef build(traces: list[dict], eval_inputs: list[str] | None = None, seed: int = 1, contamination_overlap: float = 0.8) -> dict:\n    eval_inputs = eval_inputs if eval_inputs is not None else [c[\"input\"] for c in STARTER]\n    eval_sets = [_norm(t) for t in eval_inputs]\n    report = {\"input\": len(traces), \"dropped_feedback\": 0, \"dropped_unsafe\": 0, \"pii_scrubbed\": 0, \"dropped_duplicate\": 0, \"dropped_contaminated\": 0}\n    seen, kept = set(), []\n    for t in traces:\n        if t.get(\"feedback\") == \"down\":                                              # 1. people said it was bad\n            report[\"dropped_feedback\"] += 1\n            continue\n        if MEDICAL.search(t[\"reply\"]):                                               # 2. never teach medical advice\n            report[\"dropped_unsafe\"] += 1\n            continue\n        q, found_q = redact_regex(t[\"question\"])                                     # 3. personal data out of BOTH sides\n        a, found_a = redact_regex(t[\"reply\"])\n        report[\"pii_scrubbed\"] += len(found_q) + len(found_a)\n        key = (q.lower().strip(), a.lower().strip())\n        if key in seen:                                                              # 4. exact duplicates\n            report[\"dropped_duplicate\"] += 1\n            continue\n        seen.add(key)\n        if any(_jaccard(_norm(q), e) >= contamination_overlap for e in eval_sets):  # 5. the exam must not be in the textbook\n            report[\"dropped_contaminated\"] += 1\n            continue\n        kept.append({\"messages\": [{\"role\": \"system\", \"content\": SYSTEM}, {\"role\": \"user\", \"content\": q}, {\"role\": \"assistant\", \"content\": a}]})\n    rng = random.Random(seed)                                                        # 6. split: train / validation / test\n    rng.shuffle(kept)\n    n = len(kept)\n    cut1, cut2 = int(n * 0.8), int(n * 0.9)\n    splits = {\"train\": kept[:cut1], \"validation\": kept[cut1:cut2], \"test\": kept[cut2:]}\n    report.update({k: len(v) for k, v in splits.items()})\n    return {\"splits\": splits, \"report\": report}\n\n\ndef write(result: dict, folder: str) -> None:\n    out = Path(folder)\n    out.mkdir(parents=True, exist_ok=True)\n    for name, rows in result[\"splits\"].items():\n        (out / f\"{name}.jsonl\").write_text(\"\\n\".join(json.dumps(r) for r in rows) + \"\\n\", encoding=\"utf-8\")\n\n\nif __name__ == \"__main__\":\n    from synthetic_traces import generate\n    res = build(generate())\n    write(res, HERE / \"data\")\n    print(json.dumps(res[\"report\"], indent=2))\n    print(res[\"splits\"][\"train\"][0][\"messages\"][1:])\n","ch35/configs.py":"\"\"\"The settings for a real QLoRA fine-tune of an open model. Building the config objects needs no GPU, so they are tested; TRAINING needs one.\n\nQLoRA = LoRA on top of a base model stored in 4-bit numbers, so a 7-8B-parameter model fits on a single 16-24 GB GPU.\n\"\"\"\nimport torch\nfrom peft import LoraConfig\nfrom transformers import BitsAndBytesConfig\nfrom trl import SFTConfig\n\n\ndef build_qlora_configs(output_dir: str = \"clinic-lora\", bf16: bool | None = None):\n    if bf16 is None:                                                    # 16-bit \"bfloat\" training needs a recent NVIDIA GPU; on a laptop CPU it is refused\n        bf16 = torch.cuda.is_available() and torch.cuda.is_bf16_supported()\n    quant = BitsAndBytesConfig(load_in_4bit=True,                       # store the frozen base weights in 4 bits\n                               bnb_4bit_quant_type=\"nf4\",               # 'normal float 4': a 4-bit format suited to neural-net weights\n                               bnb_4bit_use_double_quant=True,          # also compress the scaling constants\n                               bnb_4bit_compute_dtype=torch.bfloat16)   # do the maths in 16 bits\n    lora = LoraConfig(r=16, lora_alpha=32, lora_dropout=0.05, target_modules=\"all-linear\", task_type=\"CAUSAL_LM\")\n    sft = SFTConfig(output_dir=output_dir, num_train_epochs=2, learning_rate=2e-4, per_device_train_batch_size=4,\n                    gradient_accumulation_steps=4,                      # effective batch of 16 without needing the memory\n                    gradient_checkpointing=True, bf16=bf16, logging_steps=10, max_length=1024,\n                    assistant_only_loss=False, report_to=\"none\")        # see the lesson: train on replies only needs a chat template that marks them\n    return quant, lora, sft\n","ch35/dpo_pairs.py":"\"\"\"Preference data for DPO: for the same question, a reply people PREFERRED and one they rejected.\n\nWhere pairs come from: a staff member edits a bad reply (edited = chosen, original = rejected); a patient or reviewer rates two replies;\nor you pair a thumbs-up reply with a thumbs-down reply to the same question. DPO then nudges the model towards 'chosen' and away from 'rejected'.\n\"\"\"\nimport json\nfrom collections import defaultdict\n\n\ndef build_pairs(traces: list[dict]) -> list[dict]:\n    by_q = defaultdict(lambda: {\"up\": [], \"down\": []})\n    for t in traces:\n        if t.get(\"feedback\") in (\"up\", \"down\"):\n            by_q[t[\"question\"].strip().lower()][t[\"feedback\"]].append(t)\n    pairs = []\n    for q, d in by_q.items():\n        if d[\"up\"] and d[\"down\"]:\n            pairs.append({\"prompt\": d[\"up\"][0][\"question\"], \"chosen\": d[\"up\"][0][\"reply\"], \"rejected\": d[\"down\"][0][\"reply\"]})\n    return pairs\n\n\ndef corrections_to_pairs(items: list[dict]) -> list[dict]:\n    \"\"\"items: [{\"question\", \"model_reply\", \"staff_reply\"}] -> pairs with the staff version as 'chosen'.\"\"\"\n    return [{\"prompt\": i[\"question\"], \"chosen\": i[\"staff_reply\"], \"rejected\": i[\"model_reply\"]} for i in items if i[\"staff_reply\"] != i[\"model_reply\"]]\n\n\ndef write(pairs: list[dict], path: str) -> None:\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(\"\\n\".join(json.dumps(p) for p in pairs) + \"\\n\")\n","ch35/dpo_train.py":"\"\"\"DPO (direct preference optimisation) on top of the SFT adapter.   *** NOT RUN HERE: needs a GPU and a real model ***\nLearn from pairs (prompt, chosen, rejected) without training a separate reward model. `beta` controls how far the model may drift\nfrom the reference: small beta = bolder change, larger beta = stay closer.\"\"\"\nfrom datasets import load_dataset\nfrom peft import LoraConfig\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\nfrom trl import DPOConfig, DPOTrainer\n\nBASE = \"PUT-AN-OPEN-MODEL-ID-HERE\"\ntok = AutoTokenizer.from_pretrained(BASE)\nmodel = AutoModelForCausalLM.from_pretrained(BASE, device_map=\"auto\")\npairs = load_dataset(\"json\", data_files=\"data/preferences.jsonl\")[\"train\"]\n\nargs = DPOConfig(output_dir=\"clinic-dpo\", beta=0.1, learning_rate=5e-6, num_train_epochs=1, per_device_train_batch_size=2,\n                 gradient_accumulation_steps=8, bf16=True, report_to=\"none\")\ntrainer = DPOTrainer(model=model, args=args, train_dataset=pairs, processing_class=tok,\n                     peft_config=LoraConfig(r=16, lora_alpha=32, target_modules=\"all-linear\", task_type=\"CAUSAL_LM\"))\ntrainer.train()\n","ch35/lora_math.py":"\"\"\"LoRA in 25 lines of numpy, no libraries: why it needs so few parameters and what 'merging' means.\n\nA layer holds a big weight matrix W (d_out x d_in). Fine-tuning normally changes all of it. LoRA freezes W and learns a small CHANGE\nwritten as two thin matrices:   delta = (alpha / r) * B @ A      with  B: d_out x r,  A: r x d_in,  and r tiny (4 to 64).\n\"\"\"\nimport numpy as np\n\n\ndef lora_params(d_out: int, d_in: int, r: int) -> tuple[int, int]:\n    \"\"\"(parameters in the full matrix, parameters LoRA trains for it)\"\"\"\n    return d_out * d_in, r * (d_out + d_in)\n\n\ndef lora_forward(x, W, A, B, alpha, r):\n    \"\"\"What the layer computes during training: the frozen path plus the small learned path.\"\"\"\n    return x @ W.T + (alpha / r) * (x @ A.T) @ B.T\n\n\ndef merge(W, A, B, alpha, r):\n    \"\"\"After training, fold the change into W once; the result runs at exactly the original speed with no extra layers.\"\"\"\n    return W + (alpha / r) * B @ A\n\n\nif __name__ == \"__main__\":\n    full, lora = lora_params(4096, 4096, 8)\n    print(f\"one 4096x4096 layer: full {full:,}  LoRA r=8 {lora:,}  ({100 * lora / full:.2f}%)\")\n    rng = np.random.default_rng(0)\n    d, r, alpha = 64, 4, 8\n    W, A, B = rng.normal(size=(d, d)), rng.normal(size=(r, d)), rng.normal(size=(d, r))\n    x = rng.normal(size=(5, d))\n    print(\"merged weights give the same output:\", np.allclose(lora_forward(x, W, A, B, alpha, r), x @ merge(W, A, B, alpha, r).T))\n    B0 = np.zeros((d, r))\n    print(\"at the start B = 0, so the model is unchanged:\", np.allclose(lora_forward(x, W, A, B0, alpha, r), x @ W.T))\n","ch35/openai_finetune.py":"\"\"\"Hosted fine-tuning with the OpenAI API.   *** NOT RUN HERE: needs an account that still has access ***\nIMPORTANT: OpenAI's documentation (read November 2026) says it is winding down fine-tuning: new users cannot access it, and existing\ncustomers can create jobs only until 6 January 2027 (earlier if a base model is retired). Treat this as a legacy path and check the\ncurrent docs before building on it; open-weight models with LoRA (tiny_lora.py, qlora_sft.py) are the durable route.\"\"\"\nimport time\n\nfrom openai import OpenAI\n\nclient = OpenAI()\ntrain = client.files.create(file=open(\"data/train.jsonl\", \"rb\"), purpose=\"fine-tune\")\njob = client.fine_tuning.jobs.create(training_file=train.id, model=\"gpt-4.1-mini-2025-04-14\")\nwhile job.status not in (\"succeeded\", \"failed\", \"cancelled\"):\n    time.sleep(30)\n    job = client.fine_tuning.jobs.retrieve(job.id)\nprint(job.status, job.fine_tuned_model)          # use job.fine_tuned_model as the `model` in chat calls; evaluate it like any change (Chapter 31)\n","ch35/qlora_sft.py":"\"\"\"QLoRA supervised fine-tuning on the clinic dataset.   *** NOT RUN HERE: needs an NVIDIA GPU and model download ***\nThe configs in configs.py are tested; the training call below follows the TRL/PEFT documentation for the versions in requirements-ft.txt.\n\n    pip install -r requirements-ft.txt bitsandbytes\n    python qlora_sft.py\n\"\"\"\nfrom datasets import load_dataset\nfrom peft import prepare_model_for_kbit_training\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\nfrom trl import SFTTrainer\n\nfrom configs import build_qlora_configs\n\nBASE = \"PUT-AN-OPEN-MODEL-ID-HERE\"          # choose a small instruct model whose LICENCE allows your use; check its model card\n\nquant, lora, sft = build_qlora_configs()\ntok = AutoTokenizer.from_pretrained(BASE)\nmodel = AutoModelForCausalLM.from_pretrained(BASE, quantization_config=quant, device_map=\"auto\")\nmodel = prepare_model_for_kbit_training(model)\ndata = load_dataset(\"json\", data_files={\"train\": \"data/train.jsonl\", \"validation\": \"data/validation.jsonl\"})\n\ntrainer = SFTTrainer(model=model, args=sft, train_dataset=data[\"train\"], eval_dataset=data[\"validation\"], processing_class=tok, peft_config=lora)\ntrainer.train()\ntrainer.save_model(\"clinic-lora\")           # saves only the small adapter (tens of MB)\n","ch35/README.md":"# Chapter 35: fine-tuning (LoRA, QLoRA, DPO)\n\nTwo environments:\n\n    # data, maths and the dataset pipeline: the main environment is enough\n    OFFLINE=1 pytest -q test_ch35.py           # 5 pass, 2 skip without torch/peft\n\n    # the real LoRA run on a laptop CPU (about a minute)\n    python -m venv .venv-ft && source .venv-ft/bin/activate\n    pip install -r requirements-ft.txt\n    pytest -q test_ch35.py                     # 7 tests, about 30 seconds\n    python tiny_lora.py                        # a REAL LoRA fine-tune of a tiny model pre-trained in the script\n\n`build_dataset.py` turns traces into a clean training set (good examples only, no PII, no duplicates, no overlap with the evaluation set). `data/` holds the result.\n\n**Not run here:**\n- `qlora_sft.py` and `dpo_train.py` need an NVIDIA GPU and a model download. The configurations (`configs.py`, `dpo_pairs.py`) are tested; the training calls follow the TRL and PEFT documentation for the pinned versions.\n- `openai_finetune.py` needs an account. Check OpenAI's current rules for fine-tuning before relying on it.\n","ch35/requirements-ft.txt":"torch\ntransformers\npeft\naccelerate\ntrl\ndatasets\nsafetensors\nnumpy\n","ch35/synthetic_traces.py":"\"\"\"SYNTHETIC helpdesk conversations standing in for real production traces (never use real patient text in a course or a repo).\nEach record is what a trace store with text capture + staff feedback would give you:  question, reply, feedback ('up'/'down'/None).\"\"\"\nimport random\n\nDOCTORS = {\"Mehta\": \"cardiology on Monday and Wednesday\", \"Rao\": \"cardiology on Thursday and Friday\", \"Iyer\": \"orthopaedics on Tuesday and Thursday\",\n           \"Khan\": \"paediatrics on Monday, Tuesday and Friday\"}\nITEMS = {\"ECG\": 350, \"X-ray\": 450, \"blood test\": 300, \"ultrasound\": 900, \"consultation\": 500}\n\n\ndef generate(n_each: int = 60, seed: int = 7) -> list[dict]:\n    rng = random.Random(seed)\n    rows = []\n    for _ in range(n_each):                                          # scheduling\n        d = rng.choice(list(DOCTORS))\n        q = rng.choice([f\"When does Dr {d} see patients?\", f\"Which days is Dr {d} available?\", f\"Can I see Dr {d} this week? my phone is 98{rng.randint(10**7, 10**8 - 1)}\"])\n        rows.append({\"question\": q, \"reply\": f\"Dr {d} sees patients for {DOCTORS[d]}. Please call 1800-000-000 to book.\", \"feedback\": rng.choice([\"up\", None, None])})\n    for _ in range(n_each):                                          # billing\n        item, price = rng.choice(list(ITEMS.items()))\n        bill = f\"BILL-{rng.randint(1000, 9999)}\"\n        q = rng.choice([f\"Why is there a {item} charge on {bill}?\", f\"What does {bill} include for the {item}?\", f\"{bill} shows {item}, what is it?\"])\n        rows.append({\"question\": q, \"reply\": f\"{bill}: the {item} is Rs {price}. For questions about this bill, call the billing desk on 1800-000-000.\", \"feedback\": rng.choice([\"up\", None])})\n    for _ in range(n_each // 2):                                     # information\n        q = rng.choice([\"What are the OPD timings?\", \"When is the OPD open?\", \"OPD hours please\", \"What time does OPD close?\"])\n        rows.append({\"question\": q, \"reply\": \"OPD is open 9 am to 5 pm, Monday to Saturday. For anything else call 1800-000-000.\", \"feedback\": rng.choice([\"up\", None])})\n    # --- the problems a real pipeline must catch\n    rows += [{\"question\": \"How much metformin should I take?\", \"reply\": \"Take 500 mg twice a day.\", \"feedback\": None},               # unsafe medical advice\n             {\"question\": \"Can I see Dr Rao on Friday?\", \"reply\": \"idk maybe\", \"feedback\": \"down\"},                                   # rated bad\n             {\"question\": \"Why is there an ECG charge on BILL-2291?\", \"reply\": \"BILL-2291: the ECG is Rs 350. For questions about this bill, call the billing desk on 1800-000-000.\", \"feedback\": \"up\"},   # also in the evaluation set\n             {\"question\": \"What are the OPD timings?\", \"reply\": \"OPD is open 9 am to 5 pm, Monday to Saturday. For anything else call 1800-000-000.\", \"feedback\": \"up\"}]               # exact duplicate of generated rows\n    rng.shuffle(rows)\n    return rows\n","ch35/test_ch35.py":"\"\"\"Tests for Chapter 35.  Data and maths tests run anywhere; the PEFT tests need the fine-tuning environment (torch, peft, trl).\n    pytest -q test_ch35.py\"\"\"\nimport json\nimport re\n\nimport numpy as np\nimport pytest\n\nimport dpo_pairs\nimport lora_math\nfrom build_dataset import build\nfrom synthetic_traces import generate\n\n\ndef test_dataset_pipeline_removes_each_kind_of_problem():\n    traces = generate()\n    res = build(traces)\n    r = res[\"report\"]\n    assert r[\"dropped_feedback\"] == 1 and r[\"dropped_unsafe\"] == 1 and r[\"dropped_contaminated\"] == 2 and r[\"dropped_duplicate\"] > 0\n    assert r[\"pii_scrubbed\"] > 0\n    all_text = json.dumps(res[\"splits\"])\n    assert \"BILL-2291\" not in all_text                                      # an evaluation case never reaches training data\n    assert not re.search(r\"\\b98\\d{8}\\b\", all_text)                          # no phone numbers survive\n    assert \"Take 500 mg\" not in all_text and \"idk maybe\" not in all_text\n    assert sum(r[k] for k in (\"train\", \"validation\", \"test\")) == r[\"input\"] - sum(r[k] for k in r if k.startswith(\"dropped\"))\n\n\ndef test_split_is_deterministic_and_disjoint():\n    a, b = build(generate(), seed=1), build(generate(), seed=1)\n    assert a[\"splits\"] == b[\"splits\"]\n    sets = [{json.dumps(x) for x in a[\"splits\"][k]} for k in (\"train\", \"validation\", \"test\")]\n    assert not (sets[0] & sets[1]) and not (sets[0] & sets[2]) and not (sets[1] & sets[2])\n\n\ndef test_every_example_is_chat_format_with_system_user_assistant():\n    for rows in build(generate())[\"splits\"].values():\n        for r in rows:\n            assert [m[\"role\"] for m in r[\"messages\"]] == [\"system\", \"user\", \"assistant\"]\n\n\ndef test_lora_math():\n    assert lora_math.lora_params(4096, 4096, 8) == (16_777_216, 65_536)\n    rng = np.random.default_rng(1)\n    d, r, alpha = 32, 4, 8\n    W, A, B = rng.normal(size=(d, d)), rng.normal(size=(r, d)), rng.normal(size=(d, r))\n    x = rng.normal(size=(3, d))\n    assert np.allclose(lora_math.lora_forward(x, W, A, B, alpha, r), x @ lora_math.merge(W, A, B, alpha, r).T)\n    assert np.allclose(lora_math.lora_forward(x, W, A, np.zeros((d, r)), alpha, r), x @ W.T)\n\n\ndef test_dpo_pairs():\n    traces = [{\"question\": \"Can I see Dr Rao on Friday?\", \"reply\": \"Dr Rao sees cardiology on Thursday and Friday.\", \"feedback\": \"up\"},\n              {\"question\": \"Can I see Dr Rao on Friday?\", \"reply\": \"idk maybe\", \"feedback\": \"down\"},\n              {\"question\": \"Only liked\", \"reply\": \"ok\", \"feedback\": \"up\"}]\n    assert dpo_pairs.build_pairs(traces) == [{\"prompt\": \"Can I see Dr Rao on Friday?\", \"chosen\": \"Dr Rao sees cardiology on Thursday and Friday.\", \"rejected\": \"idk maybe\"}]\n    fixes = dpo_pairs.corrections_to_pairs([{\"question\": \"q\", \"model_reply\": \"a\", \"staff_reply\": \"b\"}, {\"question\": \"q2\", \"model_reply\": \"same\", \"staff_reply\": \"same\"}])\n    assert fixes == [{\"prompt\": \"q\", \"chosen\": \"b\", \"rejected\": \"a\"}]\n\n\ndef test_qlora_configs_build_without_a_gpu():\n    pytest.importorskip(\"trl\")\n    from configs import build_qlora_configs\n    quant, lora, sft = build_qlora_configs()\n    assert quant.load_in_4bit and quant.bnb_4bit_quant_type == \"nf4\" and lora.r == 16 and sft.gradient_accumulation_steps == 4\n\n\ndef test_tiny_lora_pipeline_learns_saves_reloads_and_merges(tmp_path, monkeypatch, capsys):\n    pytest.importorskip(\"peft\")\n    pytest.importorskip(\"torch\")\n    import tiny_lora\n    tiny_lora.main(base_steps=80, lora_steps=120)                          # short run: enough to check behaviour, not quality\n    out = capsys.readouterr().out\n    before = float(out.split(\"validation loss \")[1].split()[0])\n    after = float(out.split(\"AFTER    clinic validation loss \")[1].split()[0])\n    assert after < before and \"trainable\" in out\n    assert \"reloaded adapter matches the trained one: True | merged model matches: True\" in out\n","ch35/tiny_lora.py":"\"\"\"A REAL LoRA fine-tune with Hugging Face PEFT, small enough to run on a laptop CPU in about a minute.\n\nHonest scope: there is no internet to download a pretrained model here, so we first pre-train a tiny character-level GPT-2 (~0.4M parameters)\non GENERIC question-and-answer text, then LoRA-fine-tune it on the clinic dataset. The model is far too small to be useful; what is real\nis the whole pipeline and every number it prints: trainable-parameter counts, loss before and after, adapter size, saving, loading, merging.\nSwap `base` for a real open model and the rest is the same code.\n\nRun in an environment with torch, transformers and peft (see requirements-ft.txt):  python tiny_lora.py\n\"\"\"\nimport copy\nimport difflib\nimport json\nimport os\nimport random\nimport tempfile\nfrom pathlib import Path\n\nimport torch\nfrom peft import LoraConfig, PeftModel, get_peft_model\nfrom transformers import GPT2Config, GPT2LMHeadModel\n\nHERE = Path(__file__).resolve().parent\ntorch.manual_seed(0)\nrandom.seed(0)\n\n# ---------------------------------------------------------------- data\nGENERIC_Q = [(\"What is the weather like today?\", \"It is sunny with a light breeze.\"), (\"Where is the nearest bakery?\", \"The bakery is next to the post office.\"),\n             (\"When does the train leave?\", \"The train leaves at six in the evening.\"), (\"How much is a cup of tea?\", \"A cup of tea costs twenty rupees.\"),\n             (\"Which bus goes to the market?\", \"Bus number twelve goes to the market.\"), (\"Is the library open on Sunday?\", \"The library is closed on Sunday.\"),\n             (\"What time does the shop close?\", \"The shop closes at nine at night.\"), (\"Where can I buy a ticket?\", \"You can buy a ticket at the station counter.\")]\n\n\ndef generic_text(n=300):\n    return [f\"User: {q}\\nReply: {a}\\n\" for q, a in (random.choice(GENERIC_Q) for _ in range(n))]\n\n\ndef load_jsonl(name):\n    rows = [json.loads(line) for line in (HERE / \"data\" / f\"{name}.jsonl\").read_text().splitlines()]\n    return [(r[\"messages\"][1][\"content\"], r[\"messages\"][2][\"content\"]) for r in rows]\n\n\nclass CharTokenizer:\n    \"\"\"One token per character. 0 = padding, 1 = end of text.\"\"\"\n\n    def __init__(self, texts):\n        self.chars = sorted(set(\"\".join(texts)))\n        self.idx = {c: i + 2 for i, c in enumerate(self.chars)}\n\n    @property\n    def vocab_size(self):\n        return len(self.chars) + 2\n\n    def encode(self, s):\n        return [self.idx[c] for c in s if c in self.idx]\n\n    def decode(self, ids):\n        inv = {v: k for k, v in self.idx.items()}\n        return \"\".join(inv.get(i, \"\") for i in ids if i > 1)\n\n\ndef example(tok, question, reply, max_len):\n    prompt = tok.encode(f\"User: {question}\\nReply: \")\n    answer = tok.encode(reply) + [1]\n    ids = (prompt + answer)[:max_len]\n    labels = ([-100] * len(prompt) + answer)[:max_len]                  # the loss counts ONLY the reply, not the question\n    return ids, labels\n\n\ndef batch(tok, pairs, max_len=160):\n    items = [example(tok, q, a, max_len) for q, a in pairs]\n    n = max(len(i) for i, _ in items)\n    ids = torch.tensor([i + [0] * (n - len(i)) for i, _ in items])\n    labels = torch.tensor([l + [-100] * (n - len(l)) for _, l in items])\n    return ids, labels, (ids != 0).long()\n\n\ndef run_loss(model, tok, pairs):\n    model.eval()\n    with torch.no_grad():\n        ids, labels, mask = batch(tok, pairs)\n        return model(input_ids=ids, attention_mask=mask, labels=labels).loss.item()\n\n\ndef train(model, tok, pairs, steps, lr, bs=16):\n    params = [p for p in model.parameters() if p.requires_grad]\n    opt = torch.optim.AdamW(params, lr=lr)\n    model.train()\n    for _ in range(steps):\n        ids, labels, mask = batch(tok, random.sample(pairs, min(bs, len(pairs))))\n        loss = model(input_ids=ids, attention_mask=mask, labels=labels).loss\n        loss.backward()\n        opt.step()\n        opt.zero_grad()\n\n\ndef generate(model, tok, question, max_new=120):\n    model.eval()\n    ids = torch.tensor([tok.encode(f\"User: {question}\\nReply: \")])\n    with torch.no_grad():\n        out = model.generate(input_ids=ids, attention_mask=torch.ones_like(ids), max_new_tokens=max_new, do_sample=False, eos_token_id=1, pad_token_id=0)\n    return tok.decode(out[0][ids.shape[1]:].tolist())\n\n\ndef similarity(model, tok, pairs):\n    return sum(difflib.SequenceMatcher(None, generate(model, tok, q), a).ratio() for q, a in pairs) / len(pairs)\n\n\ndef count(model):\n    trainable = sum(p.numel() for p in model.parameters() if p.requires_grad)\n    return trainable, sum(p.numel() for p in model.parameters())\n\n\ndef main(base_steps=400, lora_steps=600, verbose=True):\n    train_pairs, val_pairs, test_pairs = load_jsonl(\"train\"), load_jsonl(\"validation\"), load_jsonl(\"test\")\n    generic = [(q, a) for q, a in (random.choice(GENERIC_Q) for _ in range(300))]\n    tok = CharTokenizer([f\"User: {q}\\nReply: {a}\\n\" for q, a in generic + train_pairs + val_pairs + test_pairs])\n    cfg = GPT2Config(vocab_size=tok.vocab_size, n_positions=256, n_embd=96, n_layer=3, n_head=4, bos_token_id=1, eos_token_id=1, pad_token_id=0)\n    base = GPT2LMHeadModel(cfg)\n    train(base, tok, generic, steps=base_steps, lr=3e-3)                       # stage 1: the 'pretrained' generic model\n    print(f\"base model: {count(base)[1]:,} parameters\")\n    print(f\"BEFORE   clinic validation loss {run_loss(base, tok, val_pairs):.3f}   similarity to reference replies {similarity(base, tok, test_pairs):.2f}\")\n    print(\"         base model answers:\", repr(generate(base, tok, test_pairs[0][0])[:70]))\n\n    lora = LoraConfig(r=8, lora_alpha=16, lora_dropout=0.0, target_modules=[\"c_attn\", \"c_fc\"], fan_in_fan_out=True, task_type=\"CAUSAL_LM\")\n    model = get_peft_model(copy.deepcopy(base), lora)                   # stage 2: freeze the base, add small trainable adapters\n    t, total = count(model)\n    print(f\"LoRA r=8: trainable {t:,} of {total:,} parameters ({100 * t / total:.1f}%)\")\n    train(model, tok, train_pairs, steps=lora_steps, lr=3e-3)\n    print(f\"AFTER    clinic validation loss {run_loss(model, tok, val_pairs):.3f}   similarity to reference replies {similarity(model, tok, test_pairs):.2f}\")\n    print(\"         tuned model answers:\", repr(generate(model, tok, test_pairs[0][0])[:100]))\n    print(\"         reference reply    :\", repr(test_pairs[0][1][:100]))\n\n    with tempfile.TemporaryDirectory() as d:                            # stage 3: the adapter is a tiny separate file\n        model.save_pretrained(d)\n        adapter_kb = sum(f.stat().st_size for f in Path(d).glob(\"adapter_model.*\")) / 1024\n        base_kb = sum(p.numel() * 4 for p in base.parameters()) / 1024\n        print(f\"adapter file {adapter_kb:,.0f} KB vs base weights {base_kb:,.0f} KB\")\n        reloaded = PeftModel.from_pretrained(copy.deepcopy(base), d)\n        x = batch(tok, val_pairs[:2])[0]\n        model.eval()\n        reloaded.eval()\n        same = torch.allclose(model(x).logits, reloaded(x).logits, atol=1e-5)\n        merged = model.merge_and_unload()                               # stage 4: fold the change into the weights\n        merged.eval()\n        print(\"reloaded adapter matches the trained one:\", same, \"| merged model matches:\", torch.allclose(merged(x).logits, reloaded(x).logits, atol=1e-4))\n\n\nif __name__ == \"__main__\":\n    main()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
